from collections import Counter

def _mode(values):
    return Counter(values).most_common(1)[0][0]

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = _mode(x for row in grid for x in row)
    row_lines = [r for r in range(h) if _mode(grid[r]) != background]
    col_lines = [c for c in range(w) if _mode(grid[r][c] for r in range(h)) != background]
    if len(row_lines) < 2 or len(col_lines) < 2:
        return [[background]]

    row_set, col_set = set(row_lines), set(col_lines)
    separator = _mode(grid[r][c] for r in range(h) for c in range(w)
                      if r in row_set or c in col_set)
    interior = _mode(grid[r][c] for r in range(h) for c in range(w)
                     if r not in row_set and c not in col_set)
    out, active = [], []
    for r0, r1 in zip(row_lines, row_lines[1:]):
        row = []
        for c0, c1 in zip(col_lines, col_lines[1:]):
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            if corners.count(corners[0]) == 4 and corners[0] != separator:
                row.append(corners[0])
                if corners[0] != interior:
                    active.append((len(out), len(row) - 1))
            else:
                row.append(interior)
        out.append(row)
    if not active:
        return [[interior]]
    rmin = min(r for r, c in active); rmax = max(r for r, c in active)
    cmin = min(c for r, c in active); cmax = max(c for r, c in active)
    return [row[cmin:cmax+1] for row in out[rmin:rmax+1]]

